from functools import reduce

def compose_left(functions):
    return lambda x: reduce(lambda f, g: f(g), reversed(functions), x)


def peekn(n, iterable):
    it = iter(iterable)
    result = [next(it) for _ in range(n)]
    [next(it, None) for _ in range(n, len(iterable))] # consume remaining items
    return result


def dissoc(d, key):
    result = d.copy()
    if key in result:
        del result[key]
    return result


class Compose(object):
    def __init__(self, funcs):
        self.funcs = funcs

    def __call__(self, x):
        return reduce(lambda f, g: f(g), reversed(self.funcs), x)


from collections.abc import Iterable, Mapping

def fold(iterable, func, accumulator):
    for item in iterable:
        accumulator = func(accumulator, item)
    return accumulator


def merge(left, right):
    return {**(left or {}), **(right or {})}


def merge_with(func, left, right):
    return {k: func(left.get(k, ()), right.get(k, ())) for k in set(left).union(right)}
